<template><view class="page"><text class="title">未来职业探索墙</text><text class="subtitle">现在，自己去找找你感兴趣了解的职业。</text><view v-for="item in careers" :key="item.careerId" class="card" @click="open(item)"><text class="name">{{item.careerName}}</text><text v-if="item.viewed" class="viewed">已查看</text></view><text class="tip">点击职业卡片进一步了解具体职业信息</text></view></template>
<script>
import { getCatalog, getRecord, userMessage } from '@/api/zycck'
export default { data: () => ({ recordId: '', instanceId: '', gameId: '', categoryId: '', careers: [], readOnly: false }), onLoad(o) { Object.assign(this, { recordId: o.recordId || '', instanceId: o.instanceId || '', gameId: o.gameId || '', categoryId: o.categoryId || '', readOnly: o.readOnly === '1' }); this.load() }, methods: { async load() { try { const r = await getCatalog({ instanceId: this.instanceId, gameId: this.gameId }); const d = r.data || {}; const rows = d.careers || d.items || d.questions || []; let viewed = []; if (this.recordId) { try { const rr = await getRecord(this.recordId); const raw = rr.data && ((rr.data.record && rr.data.record.viewedCareerIds) || rr.data.viewedCareerIds); viewed = Array.isArray(raw) ? raw : JSON.parse(raw || '[]') } catch (e) {} } this.careers = rows.filter(x => String(x.hasQuestion) !== '1' && (!this.categoryId || String(x.categoryId) === String(this.categoryId))).map(x => ({ ...x, careerId: x.careerId || x.careerQuestionId, careerName: x.careerName || x.name || x.title, viewed: viewed.some(id => String(id) === String(x.careerId || x.careerQuestionId)) })) } catch (e) { uni.showToast({ title: userMessage(e, '职业列表加载失败，请重试'), icon: 'none' }) } }, open(i) { uni.redirectTo({ url: `/pages/zycck/career-detail?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&categoryId=${this.categoryId}&careerId=${i.careerId}&readOnly=${this.readOnly ? '1' : '0'}` }) } } }
</script>
<style scoped>.page{padding:48rpx 30rpx;background:#f5f7fb;min-height:100vh;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;animation:pageIn .35s ease-out}.title{display:block;font-size:50rpx;font-weight:800;text-align:center;color:#1a2c4a}.subtitle{display:block;text-align:center;color:#64748b;margin:16rpx 0 30rpx}.card{display:flex;justify-content:space-between;align-items:center;padding:30rpx;background:#fff;border-radius:16rpx;margin:12rpx 0;color:#243b53;box-shadow:0 6rpx 18rpx rgba(31,41,55,.04)}.card-hover{background:#edf4ff;transform:scale(.985)}.name{font-size:30rpx}.viewed{color:#42a868;font-size:25rpx}.tip{display:block;text-align:center;color:#8a94a6;font-size:24rpx;margin-top:26rpx}@keyframes pageIn{from{opacity:0;transform:translateY(18rpx)}to{opacity:1;transform:translateY(0)}}.button-hover{transform:none!important}.card-hover{transform:none!important}.awareness-hover{transform:none!important}</style>
